'use client'

import React, { useState, useEffect, useCallback, useRef } from 'react'
import { motion, AnimatePresence, PanInfo, useAnimation } from 'framer-motion'
import SinglePostView from './SinglePostView'
import { useRouter } from 'next/navigation'

export interface Post {
    _id: string
    title: string
    slug: { current: string }
    body?: any
    description?: string
    mainImage?: any
    publishedAt?: string
    readTime?: number
    element?: string
    elementName?: string
    content?: any
}

interface PostFeedContainerProps {
    initialPosts: Post[]
    initialSlug?: string
}

export default function PostFeedContainer({ initialPosts, initialSlug }: PostFeedContainerProps) {
    const startIdx = initialSlug
        ? initialPosts.findIndex(p => p.slug.current === initialSlug)
        : 0

    const [currentIndex, setCurrentIndex] = useState(startIdx !== -1 ? startIdx : 0)
    const [direction, setDirection] = useState(0)
    const [isScrolling, setIsScrolling] = useState(false)
    const scrollTimeout = useRef<NodeJS.Timeout | null>(null)

    const router = useRouter()
    const controls = useAnimation()
    const SWIPE_THRESHOLD = 50

    // URL Update Logic
    useEffect(() => {
        const currentPost = initialPosts[currentIndex]
        if (currentPost && currentPost.slug.current) {
            router.replace(`/kinh-cac/${currentPost.slug.current}`, { scroll: false })
        }
    }, [currentIndex, initialPosts, router])

    const handleNext = useCallback(() => {
        if (currentIndex < initialPosts.length - 1 && !isScrolling) {
            setIsScrolling(true)
            setDirection(1)
            setCurrentIndex((prev) => prev + 1)
            setTimeout(() => setIsScrolling(false), 800)
        }
    }, [currentIndex, initialPosts.length, isScrolling])

    const handlePrev = useCallback(() => {
        if (currentIndex > 0 && !isScrolling) {
            setIsScrolling(true)
            setDirection(-1)
            setCurrentIndex((prev) => prev - 1)
            setTimeout(() => setIsScrolling(false), 800)
        }
    }, [currentIndex, isScrolling])

    const handleDragEnd = (_: any, info: PanInfo) => {
        const { offset, velocity } = info
        if (offset.y < -SWIPE_THRESHOLD && velocity.y < 0) {
            handleNext()
        } else if (offset.y > SWIPE_THRESHOLD && velocity.y > 0) {
            handlePrev()
        } else {
            controls.start({ y: 0 })
        }
    }

    // Wheel support for Desktop
    useEffect(() => {
        const handleWheel = (e: WheelEvent) => {
            if (isScrolling) return

            if (e.deltaY > 50) {
                handleNext()
            } else if (e.deltaY < -50) {
                handlePrev()
            }
        }

        window.addEventListener('wheel', handleWheel)
        return () => window.removeEventListener('wheel', handleWheel)
    }, [handleNext, handlePrev, isScrolling])

    const variants = {
        enter: (direction: number) => ({
            opacity: 0,
            y: direction > 0 ? 100 : -100,
            filter: "blur(15px)",
        }),
        center: {
            opacity: 1,
            y: 0,
            filter: "blur(0px)",
            transition: {
                duration: 0.8,
                ease: [0.4, 0, 0.2, 1]
            }
        },
        exit: (direction: number) => ({
            opacity: 0,
            y: direction < 0 ? 100 : -100,
            filter: "blur(15px)",
            transition: {
                duration: 0.8,
                ease: [0.4, 0, 0.2, 1]
            }
        })
    }

    const currentPost = initialPosts[currentIndex]

    return (
        <div className="h-screen w-screen bg-[#1a1a1a] relative overflow-hidden">
            <AnimatePresence initial={false} custom={direction} mode="popLayout">
                <motion.div
                    key={currentIndex}
                    custom={direction}
                    variants={variants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    drag="y"
                    dragConstraints={{ top: 0, bottom: 0 }}
                    dragElastic={0.4}
                    onDragEnd={handleDragEnd}
                    className="absolute inset-0 w-full h-full bg-[#2d2d2d]"
                >
                    <div className="w-full h-full overflow-y-auto no-scrollbar selection:bg-[#c5a059]/30">
                        <SinglePostView post={currentPost} />
                    </div>
                </motion.div>
            </AnimatePresence>

            {/* Simple Indicator */}
            <div className="absolute right-2 top-1/2 -translate-y-1/2 flex flex-col gap-3 z-50 pointer-events-none mix-blend-difference">
                {initialPosts.map((_, idx) => (
                    <div
                        key={idx}
                        className={`w-1 h-1 rounded-full transition-all duration-300 ${idx === currentIndex ? 'bg-[#c5a059] h-3' : 'bg-gray-500/50'}`}
                    />
                ))}
            </div>
        </div>
    )
}
